import { styleText } from 'node:util';
import logSymbols from 'log-symbols';
import { deploymentLabel } from "./select-deployment.js";
import { sectionHeader } from "./ui.js";
export function needsFunctions(plan) {
    return plan.deployments.some((deployment) => deployment.emission !== undefined);
}
export function needsReportLines(plan) {
    return [
        sectionHeader('Runtime needs'),
        ...plan.deployments.flatMap((deployment) => ['', ...deploymentNeedsLines(deployment)]),
    ];
}
const DETAIL = '    → ';
const REASON = '      ';
function deploymentNeedsLines(plan) {
    const { emission } = plan;
    return [
        styleText('bold', `▸ ${deploymentLabel({ name: plan.deploymentName, tag: plan.tag })}`),
        ...hostingLines(plan),
        ...(emission === undefined
            ? ['  no functions needed — the reactive session is already this deployment runtime']
            : [...drainLines(plan, emission), ...clockLines(plan, emission), ...watcherLines(emission)]),
        ...selfHostedLines(plan),
        ...warningLines(plan),
    ];
}
const HOSTING_NOTE = {
    function: '',
    durableFunction: 'no functions are emitted for these yet',
    selfHosted: 'nothing is emitted — your own process runs these',
};
const HOSTING_ORDER = ['function', 'durableFunction', 'selfHosted'];
function hostingLines(plan) {
    return [
        `  hosting: this deployment declares ${plan.runtimeKind}, and each level below inherits it`,
        ...kindLines('workflow', plan.hosting.workflows),
        ...kindLines('effect', plan.hosting.effects),
    ];
}
function kindLines(what, byKind) {
    return HOSTING_ORDER.flatMap((kind) => {
        const names = byKind[kind];
        if (names.length === 0)
            return [];
        const note = HOSTING_NOTE[kind];
        const suffix = note === '' ? '' : ` — ${note}`;
        return [`${DETAIL}${kind} ${what}(s): ${names.join(', ')}${suffix}`];
    });
}
const SELF_HOSTED_DUTIES = [
    { key: 'startInstances', duty: 'start instances of' },
    { key: 'tickDeadlines', duty: 'tick the $now deadlines of' },
    { key: 'drainEffects', duty: 'drain the effects' },
    { key: 'reevaluateParents', duty: 're-evaluate, when a child settles,' },
];
function selfHostedLines(plan) {
    const duties = SELF_HOSTED_DUTIES.flatMap(({ key, duty }) => {
        const names = plan.selfHosted[key];
        return names.length === 0 ? [] : [`${REASON}${duty} ${names.join(', ')}`];
    });
    if (duties.length === 0)
        return [];
    return ['  self-hosted: nothing below is emitted, so your own process must', ...duties];
}
function drainLines(plan, emission) {
    const declared = plan.needs.drain.effectNames;
    if (declared.length === 0)
        return [];
    return [
        `  effects: ${declared.length} declared — ${declared.join(', ')}`,
        ...emission.drains.flatMap((drain) => [
            `${DETAIL}drain function ${drain.name} runs ${drain.effectNames.join(', ')}`,
            `${REASON}triggered by an instance write matching ${drain.filter}`,
        ]),
    ];
}
function clockLines(plan, emission) {
    const { heartbeat } = emission;
    if (heartbeat === undefined)
        return [];
    const ticked = new Set(heartbeat.definitions);
    return [
        `  clock: ${heartbeat.reasons.join('; ')}`,
        ...timeSiteLines(plan.needs.heartbeat.timeSites.filter((site) => ticked.has(site.definition))),
        ...spawnSiteLines(plan.needs.heartbeat.spawnSites.filter((site) => ticked.has(site.definition))),
        `${DETAIL}scheduled function ${heartbeat.name} on ${heartbeat.schedule}`,
        ...tickedLine(heartbeat),
        ...catchUpLines(heartbeat.catchUp),
        `${REASON}a scheduled function runs at most as often as your organization's plan allows` +
            ` — every minute on Enterprise, hourly on Growth, daily on Free` +
            ` (https://www.sanity.io/docs/functions/functions-introduction) — and a schedule below` +
            ` that threshold is not guaranteed to run at the rate it asks for`,
    ];
}
function tickedLine(heartbeat) {
    if (heartbeat.definitions.length === 0) {
        return [`${REASON}ticks nothing: it exists to recover effect queues`];
    }
    return [`${REASON}ticks instances of ${heartbeat.definitions.join(', ')}`];
}
function catchUpLines(catchUp) {
    if (catchUp === undefined)
        return [];
    return [
        `${REASON}drains ${catchUp.effectNames.join(', ')} on any instance of` +
            ` ${catchUp.recoverDefinitions.join(', ')} holding one unclaimed for longer than` +
            ` ${catchUp.afterMs / 1000}s, or under a lapsed claim, completed instances included`,
        ...budgetLines(catchUp),
        `${REASON}so deploying definitions before these functions loses nothing on a plan whose` +
            ` schedule runs the beat: an effect queued in the gap is dispatched by a later beat`,
        `${REASON}one beat drains the instances it selected in sequence; budgeted dispatches are` +
            ` capped at one per beat and unbudgeted ones are not, and a backlog past the function's` +
            ` budget continues on the next beat`,
    ];
}
function budgetLines(catchUp) {
    if (catchUp.budgetedEffectNames.length === 0)
        return [];
    const budget = [
        ...(catchUp.limits.timeout === undefined ? [] : [`${catchUp.limits.timeout}s`]),
        ...(catchUp.limits.memory === undefined ? [] : [`${catchUp.limits.memory}GB`]),
    ];
    return [
        `${REASON}runs on ${budget.join(', ')}, the widest effective budget among` +
            ` ${catchUp.budgetedEffectNames.join(', ')}, and takes one of them per beat so each runs` +
            ` in a function sized to its own declaration`,
    ];
}
function timeSiteLines(sites) {
    return sites.map((site) => `${REASON}${site.definition} · ${site.stage ?? 'definition'} · ${site.address.kind} · ` +
        site.condition);
}
function spawnSiteLines(sites) {
    return sites.map((site) => `${REASON}${site.definition} · ${site.stage} · ${site.activity} · ${site.action} spawns ` +
        site.spawn.definition.name);
}
function watcherLines(emission) {
    if (emission.startWatchers.length === 0)
        return [];
    const started = [
        ...new Set(emission.startWatchers.flatMap((watcher) => watcher.definitions)),
    ].toSorted();
    return [
        `  autonomous starts: ${started.length} definition(s) — ${started.join(', ')}`,
        ...emission.startWatchers.flatMap((watcher) => [
            `${DETAIL}start watcher ${watcher.name} on ${watcher.projectId}.${watcher.dataset}` +
                ` matching ${watcher.filter} — ${watcher.definitions.join(', ')}`,
            ...(watcher.updates.kind === 'noUpdate'
                ? [
                    `${REASON}creates only: the lake rejects a change of _type, so a document cannot` +
                        ` become a watched type later, and these definitions read nothing of the subject,` +
                        ` the dataset or the clock, so each document starts once, at its creation`,
                    `${REASON}a document that existed before this watcher deployed starts only when you` +
                        ` start it explicitly (sanity-workflows start, or a script), or once the` +
                        ` definition gains a start filter reading the subject or the dataset, which makes` +
                        ` its later writes start candidates`,
                ]
                : []),
        ]),
    ];
}
function warningLines(plan) {
    return [
        ...plan.anyTypeSubjects.map((name) => `  ${logSymbols.warning} ${name} declares a subject with no types, so its watcher is not` +
            ` narrowed to any document type and every document in the dataset but the engine's` +
            ` own can invoke it, the rest of the reserved sanity. and system. namespaces included,` +
            ` which the runtime then declines — declare types unless that is intended`),
        ...plan.unnarrowedStartFilters.map((name) => `  ${logSymbols.warning} ${name} has a start filter whose truth can change without a` +
            ` write to its subject — it reads $now, another document, or its subject in a way no` +
            ` field path describes — so every write to the watched types re-checks it; narrow with` +
            ` subject fields to cut invocations, and note that a document becoming eligible by time` +
            ` alone starts on its next write`),
        ...plan.subjectlessDefinitions.map((name) => `  ${logSymbols.warning} ${name} starts autonomously but declares no subject, so no` +
            ` document write can start it and it gets no watcher`),
    ];
}
